for mode in ["group","sigint2","parent","parentmid","parentlong"]:
    A=json.load(open(f"e2e/k_old_{mode}.json")); B=json.load(open(f"e2e/k_new_{mode}.json"))
    for name in A:
        tot+=1
        # drop transient scheduler-job sightings (sub-second jobs caught by 1s polling)
