        a=norm(A[name]); b=norm(B[name])
        ma=[m for _,m in a]; mb=[m for _,m in b]
        dedup=lambda L:[x for i,x in enumerate(L) if i==0 or x!=L[i-1]]
        if dedup(ma)==dedup(mb):
            same+=1
            if len(a)==len(b): maxd=max(maxd, max(abs(x[0]-y[0]) for x,y in zip(a,b)))
        else: diffs.append((mode,name,ma,mb))
        for w,d in (("old",a),("new",b)):
            for t,m in d:
                if "FAILED error=''" in m and "cancel" not in name: fail_t.setdefault((mode,w),[]).append(t); break
print(f"{same}/{tot} trials have the same sequence of user-visible states on old and new; largest timing gap {maxd}s")
for mode,name,ma,mb in diffs: print("DIFF", mode, name, "\n   old:", ma, "\n   new:", mb)
for k,v in sorted(fail_t.items()): print(k, "dead job flips to FAILED at", min(v), "-", max(v), "s after kill (n=%d)"%len(v))
